n    /// Matches Python: scale is computed from all observations before the current batch\n    /// (y_all[0..prev_num_obs]), not just the current batch.\n    ///\n    /// # Arguments\n    ///\n    /// * `y_all` - All objective values so far (full observation history)\n    /// * `num_obs` - Total number of observations (must equal y_all.len())\n    pub fn update(\n        &mut self,\n        y_all: &ArrayView1<f64>,\n        num_obs: usize,\n    ) -> Result<(), TrustRegionError> {\n        let n = y_all.len();\n        if n == 0 || n == self.prev_num_obs {\n            return Ok(());\n        }","llbc":{"crate":"ennbo","llbc_file":"ennbo.llbc","llbc_name":"ennbo::trust_region::needs_restart","def_id":1325,"opacity":"Transparent","file":"crates/ennbo/src/trust_region.rs","span":"crates/ennbo/src/trust_region.rs:243-245","beg_line":243,"end_line":245,"inputs":1,"locals":4,"statements":10,"named_locals":["_1: self [L243]"],"sig":"fn(1 args, 4 locals, 10 stmts) -> Deduplicated","snippet":"// Charon 0.1.178 LLBC MIR [ennbo.llbc :: def_id=1325 :: Transparent]\n// Item      : ennbo::trust_region::needs_restart\n// Span      : crates/ennbo/src/trust_region.rs:243-245\n// Signature : fn(1 args, 4 locals, 10 stmts) -> Deduplicated\n// Locals    : _1: self [L243]\n  [L244] StorageLive(_0)\n  [L244] StorageLive(_2)\n  [L244] _2 := Use(Copy(_1))\n  [L244] StorageLive(_3)\n  [L244] _3 := Use(Copy(_1))\n  [L244] _0 := BinaryOp(Lt)\n  [L244] StorageDead(_3)\n  [L244] StorageDead(_2)\n  [L245] StorageDead(_1)\n  [L245] Return"},"aeneas":null,"lean_def":"Trust.restart","lean_thm":"Trust.localReset","lean_thm_module":"BauxResearch.Semantics.Trust","lean_def_module":"BauxResearch.Semantics.Trust"},{"idx":512,"id":"rust-analyzer cargo ennbo 0.4.1 trust_region/impl#[TurboTrustRegion]new().","name":"new","file":"rust/crates/ennbo/src/trust_region.rs","line":135,"language":"rust","crate":"ennbo","depth":3,"root":"optimizer_factory/create_optimizer_enn_with_overrides().","src_start":135,"src_code":"    pub fn new(num_dim: usize, config: TRLengthConfig) -> Self {\n        Self {\n            length: config.length_init,\n            failure_counter: 0,\n            success_counter: 0,\n            best_value: f64::NEG_INFINITY,\n            prev_num_obs: 0,\n            success_tolerance: 3,\n            failure_tolerance: None,\n            num_dim,\n            num_arms: None,\n            config,\n            hist_ymin: f64::INFINITY,\n            hist_ymax: f64::NEG_INFINITY,\n        }\n    }\n\n    fn incorporate_hist(&mut self, y_new: &ArrayView1<f64>) {\n        for &v in y_new.iter() {\n            self.hist_ymin = self.hist_ymin.min(v);\n            self.hist_ymax = self.hist_ymax.max(v);\n        }","llbc":{"crate":"ennbo","llbc_file":"ennbo.llbc","llbc_name":"ennbo::trust_region::new","def_id":1316,"opacity":"Transparent","file":"crates/ennbo/src/trust_region.rs","span":"crates/ennbo/src/trust_region.rs:135-150","beg_line":135,"end_line":150,"inputs":2,"locals":8,"statements":20,"named_locals":["_1: num_dim [L135]","_2: config [L135]"],"sig":"fn(2 args, 8 locals, 20 stmts) -> Deduplicated","snippet":"// Charon 0.1.178 LLBC MIR [ennbo.llbc :: def_id=1316 :: Transparent]\n// Item      : ennbo::trust_region::new\n// Span      : crates/ennbo/src/trust_region.rs:135-150\n// Signature : fn(2 args, 8 locals, 20 stmts) -> Deduplicated\n// Locals    : _1: num_dim [L135], _2: config [L135]\n  [L137] StorageLive(_0)\n  [L137] StorageLive(_3)\n  [L137] _3 := Use(Copy(_2))\n  [L143] StorageLive(_4)\n  [L143] _4 := Aggregate\n  [L144] StorageLive(_5)\n  [L144] _5 := Use(Copy(_1))\n  [L145] StorageLive(_6)\n  [L145] _6 := Aggregate\n  [L146] StorageLive(_7)\n  [L146] _7 := Use(Copy(_2))\n  [L136] _0 := Aggregate\n  [L149] StorageDead(_7)\n  [L149] StorageDead(_6)\n  [L149] StorageDead(_5)\n  [L149] StorageDead(_4)\n  [L149] StorageDead(_3)\n  [L150] StorageDead(_2)\n  [L150] StorageDead(_1)\n  [L150] Return"},"aeneas":null,"lean_def":"Trust.updateBatch","le